    val instructions: String? = null,
    @SerializedName("address_type") val addressType: String? = "Home",
    val latitude: Double? = null,
    val longitude: Double? = null,
    @SerializedName("phone_number") val phoneNumber: String? = null,
    @SerializedName("is_default") val isDefault: Boolean = false,
    val label: String? = null
) {
    val addressLine1: String get() = street
    val addressLine2: String? get() = unit
    val customerId: Int get() = userId
    val formattedAddress: String get() = listOfNotNull(street, unit?.let { "Unit $it" }, city, state, zipCode).joinToString(", ")
    val displayName: String get() = locationName?.takeIf { it.isNotEmpty() } ?: addressType ?: "Home"
}

